fn frame(t: i32) {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let m: i32 = if w < h { w } else { h };
    let rad: i32 = m / 2 - 20;
    let k: i32 = 2 + (t / 150) % 6;
    let rot: i32 = t / 12;
    host::display::clear(0x02040a);
    let mut i: i32 = 0;
    while i < 32 {
        let a1: i32 = (i + rot) & 31;
        let a2: i32 = (i * k + rot) & 31;
        let x1: i32 = cx + tab[(a1 + 8) & 31] * rad / 127;
        let y1: i32 = cy + tab[a1] * rad / 127;
        let x2: i32 = cx + tab[(a2 + 8) & 31] * rad / 127;
        let y2: i32 = cy + tab[a2] * rad / 127;
        host::display::draw_line(x1, y1, x2, y2, 0x3fb8c4);
        host::display::fill_rect(x1 - 2, y1 - 2, 4, 4, 0xf0f6ff);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "K=", 0x808080, 2);
    host::display::draw_number(40, 8, k, 0x808080, 2);
    host::display::present();
}
